'use strict';
(async()=>{
 const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
 const [data,images,world]=await Promise.all(['data.json','assets/images.json','assets/world.geo.json'].map(p=>fetch(p).then(r=>{if(!r.ok)throw Error(p);return r.json()})));
 const {works,museums}=data;let view='map',selectedMuseum=null,detailId=null,current=[],toastTimer;
 const state={q:'',kind:'全部',country:'全部',theme:'全部',favorites:false};
 let favorites=new Set();try{favorites=new Set(JSON.parse(localStorage.getItem('leonardo-favorites')||'[]'))}catch{}
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const img=w=>images[w.id]?.path||'';
 const loc=w=>w.museum?`${museums[w.museum].city} · ${museums[w.museum].name}`:'私人收藏 · 位置未确认';
 function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2200)}
 function matches(w){const m=museums[w.museum];return(!state.q||[w.title,w.en,w.description,w.medium,m?.name,m?.city,m?.country].join(' ').toLowerCase().includes(state.q.toLowerCase()))&&(state.kind==='全部'||w.kind===state.kind)&&(state.country==='全部'||(m?.country||'位置未确认')===state.country)&&(state.theme==='全部'||w.theme===state.theme)&&(!state.favorites||favorites.has(w.id))}
 const map=L.map('map',{zoomControl:true,minZoom:2,maxZoom:17,worldCopyJump:false,scrollWheelZoom:true,zoomSnap:.25,maxBounds:[[-70,-180],[85,180]],maxBoundsViscosity:.9}).setView([52,10],4);
 map.attributionControl.setPrefix('<a href="https://leafletjs.com" target="_blank" rel="noopener">Leaflet</a>');
 map.attributionControl.addAttribution('<a href="https://www.naturalearthdata.com" target="_blank" rel="noopener">Natural Earth</a> · 收藏机构近似位置');
 const highlight=new Set(['France','Italy','Germany','Poland','United Kingdom','Russia','United States of America','Vatican']);
 L.geoJSON(world,{style:f=>({color:'#c6c9b8',weight:.7,fillColor:highlight.has(f.properties.name)?'#f6f0db':'#edeedd',fillOpacity:1}),interactive:false}).addTo(map);
 const labels=L.layerGroup().addTo(map);[['法国',46.6,1.8],['意大利',41.5,15],['德国',51,10],['波兰',53,20],['英国',55,-3.5],['西班牙',40,-4],['俄罗斯',62,36],['美国',39,-100],['挪威',62,9],['瑞典',63,18]].forEach(([name,lat,lng])=>L.marker([lat,lng],{icon:L.divIcon({className:'country-label',html:name,iconSize:[80,20]}),interactive:false,keyboard:false}).addTo(labels));
 const markers=L.layerGroup().addTo(map);
 let region='europe';
 const setRegion=r=>{region=r;$('#europe').classList.toggle('selected',r==='europe');$('#world').classList.toggle('selected',r==='world');if(r==='europe')map.fitBounds([[39,-7],[62,35]],{paddingTopLeft:[25,85],paddingBottomRight:[25,55],maxZoom:4.3});else map.fitBounds([[35,-84],[63,37]],{paddingTopLeft:[20,80],paddingBottomRight:[20,60],maxZoom:4});};
 $('#europe').onclick=()=>setRegion('europe');$('#world').onclick=()=>setRegion('world');
 function chips(container,key,vals){$(container).innerHTML=['全部',...vals].map(v=>`<button type="button" class="${state[key]===v?'active':''}" aria-pressed="${state[key]===v}" data-value="${esc(v)}">${esc(v)}${key==='kind'&&v!=='全部'?`<small>${works.filter(w=>w.kind===v).length}</small>`:''}</button>`).join('');$(container).querySelectorAll('button').forEach(b=>b.onclick=()=>{state[key]=b.dataset.value;selectedMuseum=null;render()})}
 function renderFilters(){chips('#kindFilters','kind',['馆方署名','合作作品','归属争议','纸本画稿']);chips('#countryFilters','country',[...new Set(Object.values(museums).map(m=>m.country)),'位置未确认']);chips('#themeFilters','theme',[...new Set(works.map(w=>w.theme))]);$('#favCount').textContent=favorites.size;}
 function card(w){const m=museums[w.museum];return`<button class="art-card" data-work="${w.id}" aria-label="查看${esc(w.title)}"><img src="${img(w)}" alt="${esc(w.title)}" loading="lazy"><div class="card-copy"><h3>${esc(w.title)}</h3><p>${esc(w.date)}<br>${m?esc(m.city+' · '+(m.name.split(' · ')[0])):'位置未确认'}</p><span class="kind">${esc(w.kind)}${favorites.has(w.id)?' · 已收藏':''}</span></div></button>`}
 function wireCards(el){el.querySelectorAll('[data-work]').forEach(b=>b.onclick=()=>openDetail(b.dataset.work))}
 function renderGallery(){let list=[...current];if($('#sort').value==='date')list.sort((a,b)=>(+a.date.match(/\d{4}/)?.[0]||0)-(+b.date.match(/\d{4}/)?.[0]||0));if($('#sort').value==='museum')list.sort((a,b)=>loc(a).localeCompare(loc(b),'zh-CN'));$('#galleryCards').innerHTML=list.map(card).join('');wireCards($('#galleryCards'));$('#empty').hidden=!!list.length;}
 function openMuseum(id,move=true){selectedMuseum=id;const m=museums[id],ws=current.filter(w=>w.museum===id);if(!ws.length)return;const panel=$('#museumPanel');panel.hidden=false;panel.innerHTML=`<button class="close-panel" aria-label="关闭收藏机构详情">×</button><span class="eyebrow">${esc(m.country)} · ${esc(m.city)}</span><h2>${esc(m.name)}</h2><p class="museum-meta">当前筛选 ${ws.length} 件 · 收藏归属，非展出承诺</p>${ws.map(w=>`<button class="museum-work" data-work="${w.id}"><img src="${img(w)}" alt=""><span><strong>${esc(w.title)}</strong><small>${esc(w.kind)} · ${esc(w.date)}</small></span></button>`).join('')}<a href="${m.source}" target="_blank" rel="noopener">查看馆方资料 ↗</a>`;panel.querySelector('.close-panel').onclick=()=>{selectedMuseum=null;panel.hidden=true;renderShelf()};wireCards(panel);if(move)map.setView([m.lat,m.lng],Math.max(map.getZoom(),7),{animate:!matchMedia('(prefers-reduced-motion: reduce)').matches});renderShelf()}
 function renderShelf(){let list=selectedMuseum?current.filter(w=>w.museum===selectedMuseum):current;$('#shelfTitle').textContent=selectedMuseum?museums[selectedMuseum].name.split(' · ')[0]+'的作品':'从一幅画开始';$('#shelfCards').innerHTML=list.length?list.map(card).join(''):'<p class="muted">没有符合条件的作品，试试重置筛选。</p>';wireCards($('#shelfCards'))}
 function renderMarkers(){
 markers.clearLayers();const groups=[];
 Object.entries(museums).forEach(([id,m])=>{const ws=current.filter(w=>w.museum===id);if(!ws.length)return;const point=map.latLngToLayerPoint([m.lat,m.lng]);let group=groups.find(g=>point.distanceTo(g.point)<40);if(!group){group={ids:[],works:[],point,lat:m.lat,lng:m.lng};groups.push(group)}group.ids.push(id);group.works.push(...ws);});
 groups.forEach(g=>{const cities=[...new Set(g.ids.map(id=>museums[id].city))];const label=cities.length>1?cities[0]+'等 '+cities.length+' 城':cities[0];const icon=L.divIcon({className:'museum-marker',html:`<div class="marker-inner"><div class="marker-art"><img src="${img(g.works[0])}" alt=""><b>${g.works.length}</b></div><span>${esc(label)}</span></div>`,iconSize:[86,70],iconAnchor:[43,44]});L.marker([g.lat,g.lng],{icon,title:`${cities.join('、')}，${g.ids.length}个收藏机构，${g.works.length}件作品`,keyboard:true,alt:label}).on('click',()=>g.ids.length===1?openMuseum(g.ids[0]):openGroup(g)).addTo(markers)});
 }
 function openGroup(g){selectedMuseum=null;const panel=$('#museumPanel');const cities=[...new Set(g.ids.map(id=>museums[id].city))];panel.hidden=false;panel.innerHTML=`<button class="close-panel" aria-label="关闭收藏机构详情">×</button><span class="eyebrow">${g.ids.length}个收藏机构 · ${g.works.length}件作品</span><h2>${esc(cities.join(' · '))}</h2><button id="zoomGroup" class="zoom-group">放大这一区域 ↗</button>${g.ids.map(id=>`<h3 class="group-museum">${esc(museums[id].name)}</h3>${g.works.filter(w=>w.museum===id).map(w=>`<button class="museum-work" data-work="${w.id}"><img src="${img(w)}" alt=""><span><strong>${esc(w.title)}</strong><small>${esc(w.kind)}</small></span></button>`).join('')}`).join('')}`;wireCards(panel);panel.querySelector('.close-panel').onclick=()=>panel.hidden=true;$('#zoomGroup').onclick=()=>{map.fitBounds(g.ids.map(id=>[museums[id].lat,museums[id].lng]),{padding:[80,80],maxZoom:13});panel.hidden=true};
 }
 map.on('zoomend',()=>{if(current.length)renderMarkers()});

 function render(){current=works.filter(matches);renderFilters();const mapped=current.filter(w=>w.museum).length,unknown=current.length-mapped;$('#resultCount').textContent=`${current.length} 件作品`;$('#resultSubtitle').textContent=`${mapped} 件有已知收藏地${unknown?' · '+unknown+' 件位置未确认':''}`;renderMarkers();renderGallery();renderShelf();if(selectedMuseum&&current.some(w=>w.museum===selectedMuseum))openMuseum(selectedMuseum,false);else{$('#museumPanel').hidden=true;selectedMuseum=null}$('#unknownBtn').hidden=!unknown;$('#unknownBtn b').textContent=unknown;}
 const spot=works[0];$('#spotlight').innerHTML=`<img src="${img(spot)}" alt="蒙娜丽莎"><div><small>今日，从这里出发</small><h3>蒙娜丽莎</h3><p>法国 · 巴黎 · 卢浮宫</p><span class="text-link">走近这幅画 ↗</span></div>`;$('#spotlight').setAttribute('role','button');$('#spotlight').tabIndex=0;$('#spotlight').onclick=()=>openDetail('mona');$('#spotlight').onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openDetail('mona')}};
 function setView(v){view=v;$('#mapView').hidden=v!=='map';$('#galleryView').hidden=v!=='gallery';$('#mapTab').classList.toggle('active',v==='map');$('#galleryTab').classList.toggle('active',v==='gallery');$('#mapTab').setAttribute('aria-pressed',String(v==='map'));$('#galleryTab').setAttribute('aria-pressed',String(v==='gallery'));if(v==='map')requestAnimationFrame(()=>map.invalidateSize());}
 $('#mapTab').onclick=()=>setView('map');$('#galleryTab').onclick=()=>setView('gallery');$('#sort').onchange=renderGallery;
 $('#search').oninput=e=>{state.q=e.target.value.trim();selectedMuseum=null;render()};$('#onlyFav').onchange=e=>{state.favorites=e.target.checked;render()};$('#reset').onclick=()=>{Object.assign(state,{q:'',kind:'全部',country:'全部',theme:'全部',favorites:false});$('#search').value='';$('#onlyFav').checked=false;selectedMuseum=null;render();setRegion('europe')};
 $('#filterToggle').onclick=()=>{$('#sidebar').classList.toggle('open');$('#filterToggle').setAttribute('aria-expanded',String($('#sidebar').classList.contains('open')))};
 $('#unknownBtn').onclick=()=>{const w=current.find(w=>!w.museum);if(w)openDetail(w.id)};
 function openDetail(id){const w=works.find(w=>w.id===id);if(!w)return;detailId=id;const m=museums[w.museum];$('#detail').classList.remove('image-full');const picture=images[id];$('#detailContent').innerHTML=`<div class="detail-image"><button id="imageZoom" aria-label="放大或缩小画作"><img src="${img(w)}" alt="${esc(w.title)}完整图像"></button><a class="image-credit" href="${picture?.source||'#'}" target="_blank" rel="noopener">${id==='asse'?'摄影：Castello Sforzesco · CC BY-SA 4.0':'图像来源：维基共享资源 · 来源与许可 ↗'}<br>点击画作放大查看</a>${id==='asse'?'<a class="image-credit" href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0 许可 · 原图缩放展示</a>':''}</div><div class="detail-copy"><span class="badge ${w.kind==='归属争议'?'disputed':''}">${esc(w.kind)}</span><h2 id="detailTitle">${esc(w.title)}</h2><div class="english">${esc(w.en)}</div><dl><dt>年代</dt><dd>${esc(w.date)}</dd><dt>媒介</dt><dd>${esc(w.medium)}</dd><dt>收藏</dt><dd>${m?esc(m.name):'私人收藏 · 存放地点未确认'}</dd><dt>地点</dt><dd>${m?esc(m.country+' · '+m.city):'不设置地图坐标'}</dd></dl><h3>${esc(w.subtitle)}</h3><p>${esc(w.description)}</p><div class="look"><b>可以这样看</b>${esc(w.look)}</div>${w.note?`<p class="note">说明：${esc(w.note)}</p>`:''}<div class="detail-actions">${m?'<button id="locateWork" class="primary">在地图中定位 ↗</button>':''}<button id="favWork">${favorites.has(id)?'♥ 已收藏':'♡ 收藏这件作品'}</button><a href="${w.source}" target="_blank" rel="noopener">${w.kind==='归属争议'?'查阅归属资料':'馆藏资料'} ↗</a></div></div>`;$('#imageZoom').onclick=()=>$('#detail').classList.toggle('image-full');if(m)$('#locateWork').onclick=()=>{$('#detail').close();if(!matches(w)){Object.assign(state,{q:'',kind:'全部',country:'全部',theme:'全部',favorites:false});$('#search').value='';$('#onlyFav').checked=false;render()}setView('map');openMuseum(w.museum)};$('#favWork').onclick=()=>{favorites.has(id)?favorites.delete(id):favorites.add(id);try{localStorage.setItem('leonardo-favorites',JSON.stringify([...favorites]))}catch{notify('浏览器未允许保存，收藏仅在本次打开期间保留')}render();$('#favWork').textContent=favorites.has(id)?'♥ 已收藏':'♡ 收藏这件作品';};let list=current.some(x=>x.id===id)?current:works;const index=list.findIndex(x=>x.id===id);$('#detailIndex').textContent=`${index+1} / ${list.length}`;$('#prevWork').disabled=index===0;$('#nextWork').disabled=index===list.length-1;$('#prevWork').onclick=()=>openDetail(list[index-1].id);$('#nextWork').onclick=()=>openDetail(list[index+1].id);if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;history.replaceState(null,'',`#work=${id}`);}
 $('#closeDetail').onclick=()=>$('#detail').close();$('#detail').addEventListener('close',()=>{$('#detail').classList.remove('image-full');history.replaceState(null,'',location.pathname+location.search)});$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close()}});
 $('#sourceList').innerHTML='<div class="source-links">'+Object.values(museums).map(m=>`<a href="${m.source}" target="_blank" rel="noopener">${esc(m.name.split(' · ')[0])} ↗</a>`).join('')+'</div>';
 const about=()=>$('#about').showModal();['#aboutBtn','#scopeBtn','#sourcesBtn'].forEach(id=>$(id).onclick=about);$('#closeAbout').onclick=()=>$('#about').close();
 document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#sidebar').classList.add('open');$('#search').focus()}if($('#detail').open&&!['INPUT','TEXTAREA'].includes(e.target.tagName)){if(e.key==='ArrowRight'&&!$('#nextWork').disabled)$('#nextWork').click();if(e.key==='ArrowLeft'&&!$('#prevWork').disabled)$('#prevWork').click()}});
 render();setRegion('europe');const deep=new URLSearchParams(location.hash.slice(1)).get('work');if(deep)openDetail(deep);
 let wasMobile=innerWidth<760;const resize=new ResizeObserver(()=>{map.invalidateSize({pan:false});const mobile=innerWidth<760;if(mobile!==wasMobile){wasMobile=mobile;setRegion(region)}});resize.observe($('#map'));
})().catch(e=>{console.error(e);document.querySelector('main').innerHTML='<div style="padding:40px"><h2>页面资料暂时未能载入</h2><p>请刷新页面重试。也可以直接下载作品资料。</p><a href="data.json">打开作品资料</a></div>'});
